-- =====================================================================
-- TÉCNICA · FASE 1 · CORTE 15 · «EVENTO DE SUSPENSIÓN» · 80 — VERIFICACIÓN DE SOLO LECTURA (una sola consulta; apta para el editor SQL web).
-- Todas las filas deben decir OK. Nota: después de este paquete, la fila de la huella del conjunto de la verificación anterior deja de valer.
-- =====================================================================
select k, v from (
  select 1 as o, '01 las 13 RPC nuevas: security definer, search_path fijo, solo service_role' as k,
         case when (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace
                     and (p.proname like 'geoportal\_redes\_evento%' or p.proname = 'geoportal_redes_planta_sectores_fijar') and p.prosecdef and p.proconfig is not null
                     and has_function_privilege('service_role', p.oid, 'execute') and not has_function_privilege('anon', p.oid, 'execute') and not has_function_privilege('authenticated', p.oid, 'execute')
                     and not exists (select 1 from aclexplode(p.proacl) x where x.grantee = 0)) = 13 then 'OK' else 'MAL' end as v
  union all select 2, '02 ninguna función interna de redes la ejecuta la API (incluida la del bot: su permiso va en otro paquete)',
         case when not exists (select 1 from pg_proc p where p.pronamespace = 'redes'::regnamespace
                                and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute') or has_function_privilege('service_role', p.oid, 'execute'))) then 'OK' else 'MAL' end
  union all select 3, '03 huellas md5 de las 36 nuevas, de tecnica.f_avisos, de redes.f_publicar_l116 y del conjunto de funciones de redes',
         case when (select count(*) from (values ('public.geoportal_redes_evento(text,text)', 'e1c60d1fdc53332d64db9360ed164461'), ('public.geoportal_redes_evento_anular(text,text,text)', '8947de32c9f76c9bfc937a31e8bf2c39'), ('public.geoportal_redes_evento_asociar(text,text,text,text,text)', 'd97df5946041079714a86de12e1d1902'), ('public.geoportal_redes_evento_catalogo(text)', '129674a1c44946f4c81bcff95b595353'), ('public.geoportal_redes_evento_cerrar(text,text,text,text)', '1ae6ea7e5c0c5f71b5d41f752775f343'), ('public.geoportal_redes_evento_declarar(text,jsonb)', 'ddf3e36525c21605a4dbf36789082c92'), ('public.geoportal_redes_evento_desasociar(text,text,text,text,text)', 'cf6f1f7a378e8ab653be26aa9a78a4ee'), ('public.geoportal_redes_evento_regreso(text,text,text,text)', 'daa542d7d0b0f8cbb09c4f4429fbfd6a'), ('public.geoportal_redes_evento_tipo_fijar(text,text,text,boolean,text,text,text)', '72a0f1537529089418bd981a30f2fdca'), ('public.geoportal_redes_evento_vista_previa(text,jsonb)', 'cb22112ec60088390648e3394f1376d7'), ('public.geoportal_redes_eventos(text,text,integer)', '5b6e1f23c3985e69cfe4908dc3752b8a'), ('public.geoportal_redes_eventos_vigentes(text)', '30d3b3306038af969a1e7e1b75e6f5ef'), ('public.geoportal_redes_planta_sectores_fijar(text,text,text[],text)', '4446a2f9bf36d700330c0c2062a2bc9f'), ('redes.f_evento_abierto(text,text,text)', '59df33f21167b73cbc9a5049b505859e'), ('redes.f_evento_autorizar(text,text)', '1c1dc3406cf363dbe6c7a6de06e12954'), ('redes.f_evento_campo_abierto(uuid)', 'd8f0f7bb4919348768eb85d5c7e11846'), ('redes.f_evento_candidatos(geometry,boolean,timestamp with time zone,uuid)', 'dc09e88af2c5c2daa62f2c53fa8ee842'), ('redes.f_evento_clave(text)', '7c6a003aa4606fc55118d51d9e68dd44'), ('redes.f_evento_contratos(geometry,boolean,boolean)', '8dafa57412c9b41aca0a0e3652f3bf2a'), ('redes.f_evento_franja(text,timestamp with time zone,text,timestamp with time zone)', 'fb9de8c4ada4a35de44889aea9f17b62'), ('redes.f_evento_hora(timestamp with time zone)', '12bbc8120d7c066ab5ef5ec9b52d92d0'), ('redes.f_evento_json(bigint,boolean)', '4bbabe20fdf321767e3125915b7880ea'), ('redes.f_evento_l116_cerrado(bigint)', '46ee46574a4cadba5224d2f50b66b92d'), ('redes.f_evento_marcar(bigint[],text,text,text)', 'f067be6b5b0344e0d9c044f8ade679de'), ('redes.f_evento_ref_libre(text,text)', '2f1a58f701a1c3ffb1ff029c7e2bf755'), ('redes.f_evento_reporte_ref(text,text)', 'd864e2843221c97428d4d9bdce4f2b2d'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('redes.f_evento_tg_bot()', '857c47e052a5204c1c437c07d4cd77d1'), ('redes.f_evento_tg_campo()', '8a755c25a340e331b233ccadf99bb099'), ('redes.f_evento_tg_dano()', '430048038207e8bcfeedbf537e75faf8'), ('redes.f_evento_tg_l116()', 'a3959ab3a96e37539fd6507cddc3e075'), ('redes.f_evento_zona(jsonb)', '71f7f27f97954858a61fcfab9f6a692f'), ('redes.f_eventos_abiertos()', '2d265a26461ea19a01e9a81bb927b120'), ('redes.f_eventos_para_avisos(timestamp with time zone)', '755cc3b1a15fbd9c82fd34991a97216a'), ('redes.f_reporte_externo_recibir_evento(jsonb)', '92be46589b80d60ce38139e3fe44550d'), ('redes.f_sin_agua_para_avisos(timestamp with time zone,numeric)', '6a370c60ddcc409b06104f599110915a')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 36
               and md5(pg_get_functiondef('tecnica.f_avisos(boolean,boolean,timestamptz)'::regprocedure)) = 'aaa81ee57ec79080b9e76213ecea006c'
               and md5(pg_get_functiondef('redes.f_publicar_l116(bigint,text,text)'::regprocedure)) = 'bd50695e59c376c2b8dbb3b006fddbd4'
               and (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
                     where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) = 'ef7564883f523685cfe36478e0985e98' then 'OK' else 'MAL' end
  union all select 4, '04 pg-safeupdate: ninguna función con DELETE o UPDATE sin WHERE',
         coalesce((select 'MAL: ' || string_agg(distinct funcion, ', ') from redes.f_funciones_sin_where()), 'OK')
  union all select 5, '05 las 7 tablas: con RLS y sin permisos para la API; las 5 de hechos, de solo agregar',
         case when (select count(*) from pg_class c where c.relnamespace = 'redes'::regnamespace and c.relkind = 'r' and c.relrowsecurity
                     and c.relname in ('eventos_suspension', 'evento_suspension_eventos', 'evento_suspension_reportes', 'evento_tipos_asociables', 'evento_tipo_eventos', 'planta_sectores', 'planta_sector_eventos')
                     and not has_table_privilege('anon', c.oid, 'select') and not has_table_privilege('authenticated', c.oid, 'select') and not has_table_privilege('service_role', c.oid, 'select')) = 7
               and (select count(*) from pg_trigger t where not t.tgisinternal and t.tgname = 't_solo_agregar'
                     and t.tgrelid in ('redes.eventos_suspension'::regclass, 'redes.evento_suspension_eventos'::regclass, 'redes.evento_suspension_reportes'::regclass,
                                       'redes.evento_tipo_eventos'::regclass, 'redes.planta_sector_eventos'::regclass)) = 5 then 'OK' else 'MAL' end
  union all select 6, '06 los 4 disparadores de la asociación automática (bot, línea 116, daños y formato de campo), activos',
         case when (select count(*) from pg_trigger t where not t.tgisinternal and t.tgname = 't_evento_asociar' and t.tgenabled = 'O'
                     and t.tgrelid in ('redes.reporte_externo_eventos'::regclass, 'redes.l116_eventos'::regclass, 'redes.danos'::regclass, 'campo.reportes'::regclass)) = 4 then 'OK' else 'MAL' end
  union all select 7, '07 lo publicado que no se reemplaza sigue igual (recibir del bot, crear daño, cortes vigentes, sector de un punto)',
         case when (select count(*) from (values ('redes.f_reporte_externo_recibir(jsonb)', '0c37fea57363e5bdd4624438c8803398'), ('public.geoportal_redes_crear_dano(text,uuid,jsonb,text)', 'f6578d1011d2ccb8431881ab576a4a6b'), ('public.geoportal_redes_cortes_vigentes(text)', 'c09eadccc9399bb27b78dfb0ad14c8f8'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 4 then 'OK' else 'MAL' end
  union all select 8, '08 el tipo «sin_agua» está activo en el catálogo de campo y en la lista de lo que se asocia; el consecutivo EVS y los parámetros, puestos',
         case when exists (select 1 from campo.tipos_reporte t join campo.grupos_reporte g on g.id = t.grupo_id where t.codigo = 'sin_agua' and t.activo and g.codigo = 'red_acueducto')
               and (select count(*) from redes.evento_tipos_asociables where origen in ('bot', 'campo') and codigo = 'sin_agua' and clase = 'sin_agua' and asocia) = 2
               and exists (select 1 from redes.consecutivos where prefijo = 'EVS')
               and (select count(*) from redes.parametros where clave in ('evento_radio_min_m', 'evento_radio_max_m', 'evento_sectores_max', 'evento_horas_atras_max', 'evento_lista_max') and estado = 'vigente') = 5
               and exists (select 1 from tecnica.aviso_parametros where clave = 'sin_agua_ventana_h') then 'OK' else 'MAL' end
  union all select 9, 'INFO eventos (abiertos · cerrados · anulados) · reportes asociados hoy',
         (select count(*) filter (where estado = 'abierto') || ' · ' || count(*) filter (where estado = 'cerrado') || ' · ' || count(*) filter (where estado = 'anulado') from redes.v_evento_suspension)
         || ' · ' || (select count(*) from redes.f_eventos_abiertos() e cross join lateral redes.f_evento_reportes(e.id) r)
  union all select 10, 'INFO lo que se asocia (bot · línea 116 · daños · formato de campo) · plantas con sectores asignados',
         (select count(*) filter (where origen = 'bot' and asocia) || ' · ' || count(*) filter (where origen = 'l116' and asocia) || ' · ' || count(*) filter (where origen = 'dano' and asocia) || ' · ' || count(*) filter (where origen = 'campo' and asocia) from redes.evento_tipos_asociables)
         || ' · ' || (select count(distinct planta_id) from redes.planta_sectores where activo)
) t order by o;
